questionvariables.text:
plist: [[18,10,10,"AVB"],[21,20,15,"BVC"],[23,16,20,"AVB"],[16,9,16,"BVC"],[22,14,19,"AVB"],[10,17,13,"BVC"],[22,18,14,"AVB"],[10,4,10,"BVC"],[13,15,13,"AVB"],[17,19,17,"BVC"]];
/* Design: angles between opposite and neighbouring edges of a pyramid with a rectangular base, by calculation. Source: adapted from SMP Book 5 (Metric), Chapter 7, Exercise C, Q4(b) (there by drawing). */
ix: 1+rand(10); PP: plist[ix];
ll: PP[1]; ww: PP[2]; hh: PP[3]; adj: PP[4];
LS: "ABCDVOMN"; LT: [[0,0,0],[ll,0,0],[ll,ww,0],[0,ww,0],[ll/2,ww/2,hh],[ll/2,ww/2,0],[ll,ww/2,0],[ll/2,0,0]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
r4(v) := float(floor(10000*v+1/2)/10000);
t1: angd("AVC"); t2: angd(adj);
isab: is(adj = "AVB"); ss: if isab then ll else ww; sn: if isab then "AB" else "BC";
oadj: if isab then "BVC" else "AVB"; on: if isab then "BC" else "AB"; face: if isab then "VAB" else "VBC";
oth: angd(oadj); vof: float(2*atan((ss/2)/hh)*180/%pi);
SA: r4(sq("OA")); SV: r4(sq("VA")); avo: angd("AVO");
a1h: t1/2; a1d: 180-t1;
t1r: r1(t1); t2r: r1(t2); t1a: t1+0.2; t2a: t2+0.2; t1g: t1+1.0; t2g: t2+1.0; t1rad: float(t1*%pi/180); t2rad: float(t2*%pi/180);
